### Lossnay fan boost
{% set active = is_state('input_boolean.lossnay_fan_boost_active', 'on') %}
{% set until = states('input_datetime.lossnay_fan_boost_until') %}
{% set current_speed = states('select.venti_fan_speed') %}
{% set running = active and until not in ['unknown', 'unavailable', 'none'] and as_timestamp(until, 0) > as_timestamp(now()) %}
{% if running %}
{% set remaining = ((as_timestamp(until, 0) - as_timestamp(now())) / 60) | round(0) %}
<ha-alert alert-type="warning">Boost active — speed {{ current_speed }} — {{ remaining }}min remaining (until {{ as_timestamp(until, 0) | timestamp_custom('%H:%M') }})</ha-alert>
{% elif current_speed == '2' %}
<ha-alert alert-type="success">Normal speed ({{ current_speed }})</ha-alert>
{% else %}
<ha-alert alert-type="info">Current speed: {{ current_speed }} (no active boost timer)</ha-alert>
{% endif %}

### Active scenario

{% set outside_raw = states('sensor.miaomiaoce_t2_56fa_temperature') | float(none) %}
{% set outside = outside_raw - (states('input_number.livingr_venti_in_offset') | float(2)) if outside_raw is not none else none %}
{% set summer_threshold = states('input_number.livingr_summer_outside_threshold') | float(15) %}
{% set winter_threshold = states('input_number.livingr_winter_outside_threshold') | float(8) %}
{% set mild_threshold = states('input_number.livingr_mild_outside_threshold') | float(28) %}
{% set ns = (states('input_datetime.livingr_night_start') if ':' in states('input_datetime.livingr_night_start') else '0:0').split(':') %}
{% set ds = (states('input_datetime.livingr_day_start') if ':' in states('input_datetime.livingr_day_start') else '0:0').split(':') %}
{% set now_m = now().hour * 60 + now().minute %}
{% set night_m = (ns[0] | int(0)) * 60 + (ns[1] | int(0)) %}
{% set day_m = (ds[0] | int(0)) * 60 + (ds[1] | int(0)) %}
{% set is_night = (now_m >= night_m and now_m < day_m) if night_m < day_m else (now_m >= night_m or now_m < day_m) %}
{% set season = 'winter' if outside is not none and outside <= winter_threshold else 'summer' if outside is not none and outside >= summer_threshold else 'neutral' %}
{% set scenario = 'Summer night' if season == 'summer' and is_night else 'Mild summer day' if season == 'summer' and outside < mild_threshold else 'Hot summer day' if season == 'summer' else 'Winter night' if season == 'winter' and is_night else 'Winter day' if season == 'winter' else 'Neutral' %}
{% set target = states('input_number.livingr_summer_night_target') if scenario == 'Summer night' else states('input_number.livingr_target_temperature') if scenario == 'Mild summer day' else states('input_number.livingr_hot_summer_target') if scenario == 'Hot summer day' else states('input_number.livingr_winter_night_target') if scenario == 'Winter night' else states('input_number.livingr_winter_target') if scenario == 'Winter day' else 'none' %}
<ha-alert alert-type="info">Active: <b>{{ scenario }}</b> · target <b>{{ target }}</b> · outside {{ outside if outside is not none else 'n/a' }}°C</ha-alert>

### Manual override status

{% set program_on = states('automation.test_aircon_livingr_room_sensor_comfort_band') == 'on' %}
{% set active = is_state('input_boolean.livingr_manual_override', 'on') %}
{% set until = states('input_datetime.livingr_manual_override_until') %}
{% set running = active and until not in ['unknown', 'unavailable', 'none'] and as_timestamp(until, 0) > as_timestamp(now()) %}
<ha-alert alert-type="{{ 'warning' if running else ('success' if program_on else 'error') }}">{{ 'Manual override active until ' ~ until if running else ('Comfort program controls this room' if program_on else 'Comfort program is OFF - nothing is controlling this room') }}</ha-alert>

